import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080"
tok=None
def get_tok():
    global tok
    r=urllib.request.Request(B+"/token",method="POST",data=b"")
    tok=json.load(urllib.request.urlopen(r))["token"]
def get(path):
    global tok
    for _ in range(200):
        if not tok: get_tok()
        r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            if e.code==404: return None
            print(path,e.code,dict(e.headers).get("Retry-After"),body[:100])
            if e.code==401: tok=None
            ra=e.headers.get("Retry-After")
            try: w=float(ra)
            except: 
                try: w=float(json.loads(body).get("retry_after",1))
                except: w=1
            time.sleep(w)
        except Exception as e:
            print(path,"err",e); time.sleep(1)
    raise SystemExit("fail "+path)
orders={};dups=0;p=1
while p:
    d=get(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in orders:
            dups+=1
            if orders[o["id"]]!=o: print("DIFF",o,orders[o["id"]])
        else: orders[o["id"]]=o
    p=d["next"] and int(d["next"].split("page=")[1])
print(len(orders),dups)
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0
for o in orders.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o); t=t.replace(tzinfo=timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get("/customers/"+c)
    if cust[c] is None: print("missing cust",o); continue
    a=o["amount_cents"]*(100-cust[c]["discount_pct"])
    reg[cust[c]["region"]]+=(a+50)//100;n+=1
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2);print(res)
